# Writes crate/src/checker/flags_generated.rs: the flag sets and iota kinds of package checker as define_flags! sets.
# usage: python3 genflags.py <out file> [--check]
import re, subprocess, sys, tempfile, os

# The generated file is what rustfmt makes of the generator's text.
def rustfmt(text):
    fd, path = tempfile.mkstemp(suffix='.rs')
    os.write(fd, text.encode()); os.close(fd)
    subprocess.run(['rustfmt', '--edition', '2024', path], check=True)
    out = open(path).read(); os.unlink(path)
    return out

R = '/workspace/ref/typescript-go/internal/checker/'
# (file, Go type, Rust repr). The Go type name is the prefix of its constants.
SETS = [
    ('types.go', 'ExternalEmitHelpers', 'u32'), ('types.go', 'ContextFlags', 'u32'), ('types.go', 'TypeFormatFlags', 'u32'), ('types.go', 'SymbolFormatFlags', 'u32'),
    ('types.go', 'SignatureKind', 'i32'), ('types.go', 'MemberOverrideStatus', 'i32'),
    ('types.go', 'ExhaustiveState', 'u8'), ('types.go', 'MembersOrExportsResolutionKind', 'isize'),
    ('types.go', 'VarianceFlags', 'u32'), ('types.go', 'AccessFlags', 'u32'), ('types.go', 'NodeCheckFlags', 'u32'),
    ('types.go', 'TypeFlags', 'u32'), ('types.go', 'ObjectFlags', 'u32'), ('types.go', 'ElementFlags', 'u32'),
    ('types.go', 'IndexFlags', 'u32'), ('types.go', 'SignatureFlags', 'u32'), ('types.go', 'TypePredicateKind', 'i32'),
    ('relater.go', 'SignatureCheckMode', 'u32'), ('relater.go', 'MinArgumentCountFlags', 'u32'),
    ('relater.go', 'IntersectionState', 'u32'), ('relater.go', 'RecursionFlags', 'u32'), ('relater.go', 'ExpandingFlags', 'u8'),
    ('relater.go', 'RelationComparisonResult', 'u32'),
    ('checker.go', 'CheckMode', 'u32'), ('checker.go', 'WideningKind', 'i32'), ('checker.go', 'CachedTypeKind', 'i32'),
    ('checker.go', 'InferenceFlags', 'u32'), ('checker.go', 'InferencePriority', 'i32'),
    ('checker.go', 'DeclarationMeaning', 'u32'), ('checker.go', 'DeclarationSpaces', 'i32'),
    ('checker.go', 'IntrinsicTypeKind', 'i32'), ('checker.go', 'MappedTypeModifiers', 'u32'),
    ('checker.go', 'MappedTypeNameTypeKind', 'i32'), ('checker.go', 'ReferenceHint', 'i32'), ('checker.go', 'TypeFacts', 'u32'),
    ('checker.go', 'IterationUse', 'u32'), ('checker.go', 'IterationTypeKind', 'i32'),
    ('checker.go', 'UnionReduction', 'i32'),
    ('checker.go', 'IntersectionFlags', 'u32'),
    ('mapper.go', 'TypeMapperKind', 'i32'), ('jsx.go', 'JsxFlags', 'u32'),
]

def words(name):
    name = name.replace('JSDoc', 'Jsdoc')
    name = re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', name)
    return re.sub(r'([A-Z]+)([A-Z][a-z])', r'\1_\2', name)

def upper_snake(name):
    return words(name).upper()

def blocks(text):
    # Yields the lines of every `const ( ... )` block.
    out, cur = [], None
    for line in text.split('\n'):
        if cur is None:
            if re.match(r'^const \($', line):
                cur = []
        elif line.startswith(')'):
            out.append(cur); cur = None
        else:
            cur.append(line)
    return out

def strip_comment(line):
    i = line.find('//')
    return (line if i < 0 else line[:i]).strip()

def convert(expr, gotype, known):
    def ident(m):
        w = m.group(0)
        if w.startswith(gotype) and w[len(gotype):] in known:
            return 'Self::' + upper_snake(w[len(gotype):]) + '.0'
        return w
    expr = expr.replace('&^', '& !')
    expr = re.sub(r'(^|[&|(=]\s*)\^', r'\1!', expr)
    return re.sub(r'[A-Za-z_][A-Za-z0-9_]*', ident, expr)

def generate():
    lines = ['// Generated by py/genflags.py from types.go, relater.go, checker.go, mapper.go and jsx.go of typescript-go 89d5d5b. Do not edit.',
             'use crate::tscore::flags::define_flags;', '']
    problems = []
    for file, gotype, repr_ in SETS:
        text = open(R + file).read()
        entries = []
        for block in blocks(text):
            specs = [strip_comment(l) for l in block]
            specs = [s for s in specs if s and not s.startswith('/*') and not s.startswith('*')]
            if not any(re.match(r'^' + re.escape(gotype) + r'[A-Za-z0-9_]*\s+' + re.escape(gotype) + r'\b', s) for s in specs):
                continue
            iota_expr, index = None, -1
            for s in specs:
                index += 1
                m = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)(?:\s+([A-Za-z_][A-Za-z0-9_.]*))?(?:\s*=\s*(.+))?$', s)
                if not m:
                    problems.append(f'{file} {gotype}: cannot read "{s}"'); continue
                name, typ, expr = m.group(1), m.group(2), m.group(3)
                if expr is not None:
                    iota_expr = expr if 'iota' in expr else None
                if expr is None:
                    if iota_expr is None:
                        problems.append(f'{file} {gotype}: {name} has no value'); continue
                    expr = iota_expr
                if not name.startswith(gotype):
                    continue
                if typ is not None and typ != gotype:
                    continue
                entries.append((name[len(gotype):], expr.replace('iota', str(index))))
        if not entries:
            problems.append(f'{file}: no constants of {gotype}'); continue
        known = {e[0] for e in entries}
        rust_type = gotype[0].upper() + gotype[1:]
        lines.append(f'define_flags!({rust_type}: {repr_} {{')
        for short, expr in entries:
            if short == 'None':
                # The macro defines NONE as zero.
                if convert(expr, gotype, known).strip() != '0':
                    problems.append(f'{gotype}None is not zero')
                continue
            lines.append(f'    {upper_snake(short)} = {convert(expr, gotype, known)},')
        lines.append('});')
        lines.append('')
    return rustfmt('\n'.join(lines).rstrip('\n') + '\n'), problems

if __name__ == '__main__':
    out = sys.argv[1]
    text, problems = generate()
    for p in problems:
        print('problem:', p)
    if '--check' in sys.argv:
        if open(out).read() != text:
            print('flags_generated.rs differs from the generator output'); sys.exit(1)
        print('flags_generated.rs: no diff,', len(problems), 'problems')
    else:
        open(out, 'w').write(text)
        print('wrote', out, text.count('define_flags!') - 0, 'sets,', len(problems), 'problems')
    sys.exit(1 if problems else 0)
